export const DashboardIssueSchema = Type.Object({
  author: Type.String(),
  id: Type.Number(),
  title: Type.String(),
  number: Type.Number(),
  permalink: Type.String(),
  commentCount: Type.Number(),
  createdAt: Type.String(),
  updatedAt: Type.String(),
  repository: Type.Object({
    id: Type.Number(),
    isPrivate: Type.Boolean(),
    name: Type.String(),
    ownerLogin: Type.String(),
    copilotAgentEnabled: Type.Boolean(),
  }),
  readByCurrentUser: Type.Boolean(),
  assignedToCopilot: Type.Boolean(),
})

export type DashboardIssue = Type.Static<typeof DashboardIssueSchema>

export const DashboardIssueValidator = Compile(Type.Array(DashboardIssueSchema))

