// eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-imports
import type {UITask} from '@github-ui/agent-sessions/types/task'
import {DiffStats} from '@github-ui/diffs/DiffStats'
// eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-imports
import {getLeadingVisualIconAttributes} from '@github-ui/agent-sessions/utils/get-leading-visual-icon-attributes'
import {DotFillIcon, GitPullRequestIcon, VscodeIcon} from '@primer/octicons-react'
import {RelativeTime} from '@primer/react'
// eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-imports
import {WithShimmerEffect} from '@github-ui/copilot-chat/components/WithShimmerEffect'
// eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-imports
import {getReadableSessionState} from '@github-ui/agent-sessions/types/session'
// eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-imports
import {generateTaskPath} from '@github-ui/agent-sessions/utils/generate-task-path'
import {isFeatureEnabled} from '@github-ui/feature-flags'
import {useClickAnalytics} from '@github-ui/use-analytics'
import {clsx} from 'clsx'
import {useCallback} from 'react'
import {
  DashboardListItem,
  DashboardListItemActions,
  DashboardListItemDescription,
  DashboardListItemLeadingVisual,
  DashboardListItemTitle,
  DashboardListItemTrailingActionsMenu,
} from './DashboardListView'
import styles from './DashboardListView.module.css'
import {useVSCodeAgentSessionUrl} from '../hooks/useVSCodeAgentSessionUrl'
import {attemptOpenUrlWithFallback} from '../utils/attempt-open-url-with-fallback'

interface AgentsListItemProps {
  task: UITask
  onTitleClick: () => void
  analyticsCategory?: string
}

export function AgentsListItem({task, onTitleClick, analyticsCategory = 'agents_list'}: AgentsListItemProps) {
  const title = task.pull?.title ?? `Creating ${task.problemStatement ?? 'task'}`
  // We know that nwo will be defined if isOptimistic is true, but TypeScript can't infer this
  // Use a fallback of empty string to satisfy the type checker
  const repoNameWithOwner = task.isOptimistic ? task.nwo ?? '' : task.pull.repository_nwo
  const prState = task.pull?.state ?? 'open'
  const prInMergeQueue = task.pull?.inMergeQueue ?? false

  const leadingVisualAttributes = task.isOptimistic
    ? {icon: DotFillIcon, color: 'var(--fgColor-attention)'}
    : getLeadingVisualIconAttributes(prState, prInMergeQueue, task.latest_session_state)

  let taskUrl = task.pull?.url
  if (isFeatureEnabled('copilot_swe_agent_progress_commands') && task.pull) {
    taskUrl = generateTaskPath(task.pull.global_relay_id, task.latest_session_id)
  }

  const renderDescriptionText = () => {
    if (task.isOptimistic) {
      return `${repoNameWithOwner} · Initializing pull request...`
    }

    const relativeTimeText = task.latest_session_state === 'completed' ? 'Completed' : 'Started'
    const revisionTextWithTrailingSeparator = task.session_count > 1 ? `${task.session_count} revisions ·` : ''
    const currentLogText =
      prState === 'merged'
        ? 'Merged'
        : prState === 'closed'
          ? 'Closed'
          : prInMergeQueue
            ? 'Queued to merge'
            : getReadableSessionState(task.latest_session_state)

    return (
      <>
        {repoNameWithOwner}#{task.pull.number} · {relativeTimeText}{' '}
        <RelativeTime format="relative" datetime={task.latest_session_updated_at} /> ·{' '}
        {revisionTextWithTrailingSeparator} {currentLogText}
      </>
    )
  }

  const {sendClickAnalyticsEvent} = useClickAnalytics()

  const onClickViewPullRequest = useCallback(() => {
    sendClickAnalyticsEvent({category: analyticsCategory, action: 'click.view_pull_request_from_agent_task'})
  }, [sendClickAnalyticsEvent, analyticsCategory])

  const showOpenAgentSessionInVSCodeAction = isFeatureEnabled('dashboard_lists_open_agent_session_in_vscode')

  const vsCodeAgentSessionUrl = useVSCodeAgentSessionUrl({
    repositoryNwo: repoNameWithOwner,
    globalId: task.resource_global_id,
    headRefName: task.pull?.head_ref_name,
  })

  const onClickOpenAgentSessionInVSCode = useCallback(() => {
    sendClickAnalyticsEvent({category: analyticsCategory, action: 'click.open_agent_session_in_vscode'})

    if (!vsCodeAgentSessionUrl) return

    attemptOpenUrlWithFallback(vsCodeAgentSessionUrl, repoNameWithOwner)
  }, [sendClickAnalyticsEvent, analyticsCategory, repoNameWithOwner, vsCodeAgentSessionUrl])

  return (
    <DashboardListItem className={clsx(task.isOptimistic && styles.optimisticItem, styles.fadeIn)}>
      <DashboardListItemLeadingVisual>
        {leadingVisualAttributes.icon && (
          <div
            style={{
              color: leadingVisualAttributes.color,
              marginTop: task.latest_session_state === 'in_progress' && !task.isOptimistic ? '3px' : '1px',
              // Adds marginTop to account for spinning icon being off-center
            }}
          >
            <leadingVisualAttributes.icon />
          </div>
        )}
      </DashboardListItemLeadingVisual>
      {task.isOptimistic ? (
        <WithShimmerEffect className="fgColor-muted">
          <DashboardListItemTitle as="div">{title}</DashboardListItemTitle>
        </WithShimmerEffect>
      ) : (
        <DashboardListItemTitle onClick={onTitleClick} as="a" href={taskUrl}>
          {title}
        </DashboardListItemTitle>
      )}
      <DashboardListItemDescription>{renderDescriptionText()}</DashboardListItemDescription>
      <DashboardListItemActions>
        {task.latest_session_state !== 'in_progress' && task.pull?.pr_diff_summary && (
          <DiffStats
            linesAdded={task.pull.pr_diff_summary.lines_added}
            linesChanged={task.pull.pr_diff_summary.lines_changed}
            linesDeleted={task.pull.pr_diff_summary.lines_deleted}
          />
        )}
      </DashboardListItemActions>
      {!task.isOptimistic && (
        <DashboardListItemTrailingActionsMenu aria-label="Task actions">
          <DashboardListItemTrailingActionsMenu.Item
            icon={GitPullRequestIcon}
            label="View pull request"
            href={task.pull.url}
            onClick={onClickViewPullRequest}
          />
          {showOpenAgentSessionInVSCodeAction && vsCodeAgentSessionUrl && (
            <DashboardListItemTrailingActionsMenu.Item
              icon={VscodeIcon}
              label="Open session in VS Code"
              onClick={onClickOpenAgentSessionInVSCode}
            />
          )}
        </DashboardListItemTrailingActionsMenu>
      )}
    </DashboardListItem>
  )
}

try{ AgentsListItem.displayName ||= 'AgentsListItem' } catch {}